source("pre.R")
meta <- function(x) paste(.Call(zutable:::zt_sorted_meta, x), collapse = ",")
ops <- list(sortd = function(w) sort(w, decreasing = TRUE), order = function(w) order(w), orderd = function(w) order(w, decreasing=TRUE), unique = function(w) unique(w), rev = function(w) rev(w), match = function(w) match(2, w), fi = function(w) findInterval(2, w), inn = function(w) 2 %in% w, min = function(w) min(w), range = function(w) range(w), sum = function(w) sum(w), mean = function(w) mean(w), plus = function(w) w + 1L, sub = function(w) w[2:3], print = function(w) capture.output(print(w)), dup = function(w) duplicated(w), tab = function(w) table(w), rank = function(w) rank(w), cumsum = function(w) cumsum(w), identical = function(w) identical(w, w), ser = function(w) serialize(w, NULL), keysort = function(w) key_sort(w), keyorder = function(w) key_order(w), grp = function(w) grp(w), zut = function(w) zutable(k = w), zq = function(w) zutable(k = w)[k > 1], str = function(w) capture.output(str(w)), asvec = function(w) as.vector(w), asnum = function(w) as.numeric(w), isna = function(w) is.na(w), paste = function(w) paste(w), which = function(w) which(w > 1), diff = function(w) diff(w), median = function(w) median(w), quantile = function(w) quantile(w), var = function(w) var(w), summary = function(w) summary(w), split = function(w) split(w, w), lapply = function(w) lapply(w, identity), c = function(w) c(w, w), rep = function(w) rep(w, 2), fmt = function(w) format(w), df = function(w) data.frame(w), merge = function(w) merge(data.frame(w), data.frame(w)), cut = function(w) cut(w, 2), tabulate = function(w) tabulate(w), pmin = function(w) pmin(w, 2L), ifelse = function(w) ifelse(w > 1, w, 0L), all.eq = function(w) all.equal(w, w), hash = function(w) rlang_absent <- NULL)
for (t in c("integer", "double")) for (nm in names(ops)) {
  src <- c(3L, 1L, 2L, 5L); storage.mode(src) <- t
  w <- key_sort(src); m0 <- meta(w); invisible(tryCatch(ops[[nm]](w), error = function(e) cat("E", nm, conditionMessage(e), "\n")))
  if (meta(w) != m0) cat(t, nm, "dropped marks:", m0, "->", meta(w), "\n")
}
